luci-app-firewall.json.text:
{
	"admin/network/firewall": {
		"title": "Firewall",
		"order": 60,
		"action": {
			"type": "alias",
			"path": "admin/network/firewall/zones"
		},
		"depends": {
			"acl": [ "luci-app-firewall" ],
			"fs": { "/sbin/fw3": "executable" },
			"uci": { "firewall": true }
		}
	},

	"admin/network/firewall/zones": {
		"title": "General Settings",
		"order": 10,
		"action": {
			"type": "view",
			"path": "firewall/zones"
		}
	},

	"admin/network/firewall/forwards": {
		"title": "Port Forwards",
		"order": 20,
		"action": {
			"type": "view",
			"path": "firewall/forwards"
		}
	},

	"admin/network/firewall/rules": {
		"title": "Traffic Rules",
		"order": 30,
		"action": {
			"type": "view",
			"path": "firewall/rules"
		}
	},

	"admin/network/firewall/snats": {
		"title": "NAT Rules",
		"order": 40,
		"action": {
			"type": "view",
			"path": "firewall/snats"
		}
	},

	"admin/network/firewall/ipsets": {
		"title": "IP Sets",
		"order": 45,
		"action": {
			"type": "view",
			"path": "firewall/ipsets"
		}
	},

	"admin/network/firewall/custom": {
		"title": "Custom Rules",
		"order": 50,
		"action": {
			"type": "view",
			"path": "firewall/custom"
		},
		"depends": {
			"fs": { "/usr/share/fw3/helpers.conf": "file" }
		}
	}
}

luci-base.json.text:
{
	"admin": {
		"title": "Administration",
		"order": 10,
		"action": {
			"type": "firstchild",
			"recurse": true
		},
		"auth": {
			"methods": [ "cookie:sysauth_https", "cookie:sysauth_http" ],
			"login": true
		}
	},

	"admin/status": {
		"title": "Status",
		"order": 10,
		"action": {
			"type": "firstchild",
			"preferred": "overview",
			"recurse": true
		}
	},

	"admin/system": {
		"title": "System",
		"order": 20,
		"action": {
			"type": "firstchild",
			"preferred": "system",
			"recurse": true
		}
	},

	"admin/services": {
		"title": "Services",
		"order": 30,
		"action": {
			"type": "firstchild",
			"recurse": true
		}
	},

	"admin/nas": {
		"title": "NAS",
		"order": 40,
		"action": {
			"type": "firstchild",
			"recurse": true
		}
	},

	"admin/vpn": {
		"title": "VPN",
		"order": 50,
		"action": {
			"type": "firstchild",
			"recurse": true
		}
	},

	"admin/network": {
		"title": "Network",
		"order": 60,
		"action": {
			"type": "firstchild",
			"recurse": true
		}
	},

	"admin/translations/*": {
		"action": {
			"type": "function",
			"module": "luci.controller.admin.index",
			"function": "action_translations"
		},
		"auth": {}
	},

	"admin/ubus/*": {
		"action": {
			"type": "function",
			"module": "luci.controller.admin.index",
			"function": "action_ubus"
		},
		"auth": {}
	},

	"admin/logout": {
		"title": "Log out",
		"order": 999,
		"action": {
			"type": "function",
			"module": "luci.controller.admin.index",
			"function": "action_logout"
		},
		"depends": {
			"acl": [ "luci-base" ]
		},
		"firstchild_ineligible": true
	},

	"admin/uci": {
		"action": {
			"type": "firstchild"
		}
	},

	"admin/uci/revert": {
		"action": {
			"type": "function",
			"module": "luci.controller.admin.uci",
			"function": "action_revert",
			"post": true
		}
	},

	"admin/uci/apply_rollback": {
		"cors": true,
		"action": {
			"type": "function",
			"module": "luci.controller.admin.uci",
			"function": "action_apply_rollback",
			"post": true
		},
		"auth": {
			"methods": [ "cookie:sysauth_https", "cookie:sysauth_http" ]
		}
	},

	"admin/uci/apply_unchecked": {
		"cors": true,
		"action": {
			"type": "function",
			"module": "luci.controller.admin.uci",
			"function": "action_apply_unchecked",
			"post": true
		},
		"auth": {
			"methods": [ "cookie:sysauth_https", "cookie:sysauth_http" ]
		}
	},

	"admin/uci/confirm": {
		"cors": true,
		"action": {
			"type": "function",
			"module": "luci.controller.admin.uci",
			"function": "action_confirm"
		},
		"auth": {}
	},

	"admin/menu": {
		"action": {
			"type": "function",
			"module": "luci.controller.admin.index",
			"function": "action_menu"
		},
		"auth": {}
	}
}

